head.b:skin:
#navbar-iframe, .navbar, .header, #header, .feed-links, .status-msg-wrap { display: none !important; }
.blogger-hidden-section { display: none !important; visibility: hidden !important; height: 0 !important; width: 0 !important; overflow: hidden !important; }
html, body { margin: 0; padding: 0; width: 100%; min-height: 100%; background-color: #f8fafc; font-family: 'Hind Siliguri', -apple-system, BlinkMacSystemFont, sans-serif; }
#root { min-height: 100vh; display: flex; flex-direction: column; }
.loader-container { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #f8fafc; color: #1e293b; font-family: sans-serif; }
.spinner { width: 44px; height: 44px; border: 4px solid #e2e8f0; border-top-color: #15803d; border-radius: 50%; animation: spin 0.8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

body.script:
try {
  window.__BLOGGER_PAGE_TYPE__ = "<data:blog.pageType/>";
  window.__BLOGGER_POST_ID__ = "<data:blog.postId/>";
  window.__BLOGGER_PAGE_NAME__ = "<data:blog.pageName/>";
  window.__BLOGGER_URL__ = "<data:blog.url/>";
} catch(e) {}

(function() {
  var BUNDLE_ENDPOINT = "https://ebookbazar-95586-default-rtdb.firebaseio.com/ebooks/app_bundle.json";
  var CACHE_KEY = "eb_react_bundle_cache_v7";

  function mountApp(css, js) {
    if (window.__app_mounted) return;
    window.__app_mounted = true;

    // Inject App CSS
    var style = document.createElement("style");
    style.type = "text/css";
    style.appendChild(document.createTextNode(css));
    document.head.appendChild(style);

    // Inject App React Module Script
    var blob = new Blob([js], { type: "application/javascript" });
    var script = document.createElement("script");
    script.type = "module";
    script.src = URL.createObjectURL(blob);
    document.body.appendChild(script);

    // Remove initial spinner
    var loader = document.getElementById("initial-loader");
    if (loader) {
      setTimeout(function() {
        if (loader && loader.parentNode) loader.parentNode.removeChild(loader);
      }, 300);
    }
  }

  // Try LocalStorage Cache for instant sub-second boot
  try {
    var cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      var parsed = JSON.parse(cached);
      if (parsed && parsed.js && parsed.css) {
        mountApp(parsed.css, parsed.js);
      }
    }
  } catch (e) {
    console.warn("Cache load failed:", e);
  }

  // Fetch live bundle from Firebase
  fetch(BUNDLE_ENDPOINT)
    .then(function(res) { return res.json(); })
    .then(function(data) {
      if (data && data.js && data.css) {
        try {
          localStorage.setItem(CACHE_KEY, JSON.stringify(data));
        } catch (e) {}

        if (!window.__app_mounted) {
          mountApp(data.css, data.js);
        }
      }
    })
    .catch(function(err) {
      console.error("Bundle load error:", err);
      var loader = document.getElementById("initial-loader");
      if (loader) {
        loader.innerHTML = "<p style='color:red;font-weight:bold;'>প্রজেক্ট লোড করতে ব্যর্থ হয়েছে। ইন্টারনেট কানেকশন চেক করুন।</p>";
      }
    });
})();
